const d = $input.item.json;

const videoId = d.id ?? d.video_id ?? null;
const driveFileId = d.drive_file_id ?? d.driveFileId ?? null;
const filename = d.filename ?? d.name ?? '';

if (!videoId || !driveFileId) {
  throw new Error('Entrada invalida: esperado id e drive_file_id vindos do Workflow 01');
}

// Sanitizacao: o ID do Drive vai virar parte de um caminho passado para o
// shell no node do ffmpeg. Restringir a [A-Za-z0-9_-] elimina qualquer
// possibilidade de injecao de comando via nome de arquivo.
const safeId = String(driveFileId).replace(/[^A-Za-z0-9_-]/g, '');
if (!safeId) {
  throw new Error('drive_file_id sem caracteres validos: ' + driveFileId);
}

const ext = filename.includes('.') ? filename.split('.').pop().toLowerCase() : 'mp4';

return {
  json: {
    videoId,
    driveFileId,
    filename,
    safeId,
    videoPath: `/tmp/atlas_${safeId}.${ext}`,
    audioPath: `/tmp/atlas_${safeId}.mp3`,
  },
};

const r = $input.item.json;
const ctx = $('Preparar Contexto').item.json;

const pad = (n, size) => String(n).padStart(size, '0');

// Converte segundos (float) para o formato de tempo do SRT: HH:MM:SS,mmm
function toSrtTime(seconds) {
  const total = Math.max(0, Number(seconds) || 0);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = Math.floor(total % 60);
  const ms = Math.round((total - Math.floor(total)) * 1000);
  return `${pad(h, 2)}:${pad(m, 2)}:${pad(s, 2)},${pad(ms, 3)}`;
}

const segments = Array.isArray(r.segments) ? r.segments : [];
const transcript = (r.text || '').trim();

// Sem segmentos (audio muito curto ou silencio) ainda geramos um SRT de um
// bloco so, para nunca deixar o campo vazio quando existe texto.
let srt;
if (segments.length) {
  srt = segments
    .map((seg, i) => `${i + 1}\n${toSrtTime(seg.start)} --> ${toSrtTime(seg.end)}\n${(seg.text || '').trim()}`)
    .join('\n\n') + '\n';
} else if (transcript) {
  srt = `1\n00:00:00,000 --> ${toSrtTime(r.duration || 5)}\n${transcript}\n`;
} else {
  srt = '';
}

return {
  json: {
    videoId: ctx.videoId,
    driveFileId: ctx.driveFileId,
    filename: ctx.filename,
    language: r.language || null,
    transcript,
    srt,
    model: 'whisper-large-v3-turbo',
    durationSeconds: r.duration ?? null,
    totalSegmentos: segments.length,
  },
};

const j = $input.item.json;
const ctx = $('Preparar Contexto').item.json;

const mensagem =
  j.error?.message ||
  j.error ||
  j.message ||
  'Falha desconhecida no Workflow 02';

return {
  json: {
    videoId: ctx.videoId,
    filename: ctx.filename,
    erro: String(mensagem).slice(0, 2000),
  },
};
